INSERT INTO member(name, email, age) VALUES('윤광철', 'KwangcheolYoon@campus.com', 43);
INSERT INTO member(name, email, age) VALUES('공미영', 'MiyeongKong@campus.com', 23);
INSERT INTO member(name, email, age) VALUES('김도윤', 'DoyunKim@campus.com', 10);
INSERT INTO article (title, description, created, updated, member_id) VALUES
    ('비 오는 날 창가에서 읽은 책', '빗소리를 들으며 미뤄 둔 소설을 읽었어요. 따뜻한 차 한 잔을 곁들이니 오후가 금방 지나갔습니다.', '2025-07-01 10:00:00', '2025-07-01 10:00:00', @seojun_id),
    ('새벽 시장에서 장을 봤어요', '아침 일찍 갔더니 채소가 싱싱했어요. 애호박과 두부를 사 와서 된장찌개를 끓였습니다.', '2025-07-02 10:00:00', '2025-07-02 10:00:00', @seojun_id),
    ('오래된 운동화를 깨끗이 빨았어요', '흙 묻은 밑창을 솔로 닦고 그늘에 말렸어요. 새 신발은 아니지만 다시 신고 나가고 싶어졌습니다.', '2025-07-03 10:00:00', '2025-07-03 10:00:00', @seojun_id),
    ('우리 동네 산책길에 벚꽃이 피었어요', '매일 지나던 길이 분홍빛으로 바뀌었어요. 점심을 먹고 잠깐 걸었는데 사진을 여러 장 찍었습니다.', '2025-07-04 10:00:00', '2025-07-04 10:00:00', @seojun_id),
    ('처음 만든 오므라이스는 모양이 아쉬웠어요', '달걀을 접다가 찢어졌지만 맛은 괜찮았어요. 다음에는 불을 조금 약하게 해 보려고 합니다.', '2025-07-05 10:00:00', '2025-07-05 10:00:00', @seojun_id),
    ('주말에 작은 미술관에 다녀왔어요', '동네 풍경을 그린 전시가 열리고 있었어요. 익숙한 골목을 그림으로 보니 새롭게 느껴졌습니다.', '2025-07-06 10:00:00', '2025-07-06 10:00:00', @seojun_id),
    ('책상 위 케이블을 정리했어요', '충전선을 용도별로 묶고 이름표를 붙였어요. 필요한 선을 바로 찾을 수 있어서 한결 편해졌습니다.', '2025-07-07 10:00:00', '2025-07-07 10:00:00', @seojun_id),
    ('버스로 떠난 당일 바다 여행', '기차표를 구하지 못해 버스를 탔어요. 해변에서 파도 소리를 듣고 돌아오는 것만으로도 좋았습니다.', '2025-07-08 10:00:00', '2025-07-08 10:00:00', @seojun_id),
    ('오랜만에 손편지를 썼어요', '멀리 사는 친구에게 엽서를 보냈어요. 짧은 안부인데도 손으로 쓰려니 여러 번 고쳐 적게 되네요.', '2025-07-09 10:00:00', '2025-07-09 10:00:00', @seojun_id),
    ('창문 밖 참새들이 아침을 깨웠어요', '화단 근처에서 참새들이 모여 지저귀었어요. 잠깐 보고 있었더니 출근 준비가 늦어질 뻔했습니다.', '2025-07-10 10:00:00', '2025-07-10 10:00:00', @seojun_id),
    ('도서관에서 빌린 여행 에세이', '낯선 도시에서 천천히 걷는 이야기가 마음에 들었어요. 저도 다음 여행에서는 일정을 조금 줄여 보려고 해요.', '2025-07-11 10:00:00', '2025-07-11 10:00:00', @seojun_id),
    ('냉장고에 남은 채소로 카레를 끓였어요', '당근과 양파에 버섯도 조금 넣었어요. 남은 재료를 쓰고 나니 냉장고가 한결 깔끔해졌습니다.', '2025-07-12 10:00:00', '2025-07-12 10:00:00', @seojun_id),
    ('자전거 타이어에 바람을 넣었어요', '페달이 무겁게 느껴져 확인해 보니 공기가 부족했어요. 바람을 채우고 가까운 공원까지 다녀왔습니다.', '2025-07-13 10:00:00', '2025-07-13 10:00:00', @seojun_id),
    ('밤 산책 중 만난 고양이', '편의점 앞에서 고양이 한 마리가 졸고 있었어요. 멀리서 조용히 보고 길을 지나왔습니다.', '2025-07-14 10:00:00', '2025-07-14 10:00:00', @seojun_id),
    ('처음으로 필름 사진을 인화했어요', '어떻게 찍혔을지 기다리는 시간이 길었어요. 조금 흔들린 사진도 그날 분위기가 남아 있어 마음에 듭니다.', '2025-07-15 10:00:00', '2025-07-15 10:00:00', @seojun_id),
    ('가족과 함께 만두를 빚었어요', '누구 만두가 더 예쁜지 이야기하며 만들었어요. 모양은 제각각이지만 찜기에 가득 찬 모습을 보니 뿌듯했습니다.', '2025-07-16 10:00:00', '2025-07-16 10:00:00', @seojun_id),
    ('방 한쪽에 작은 독서 공간을 만들었어요', '의자를 창가로 옮기고 옆에 조명을 뒀어요. 퇴근 후 휴대전화 대신 책을 펼칠 자리가 생겼습니다.', '2025-07-17 10:00:00', '2025-07-17 10:00:00', @seojun_id),
    ('점심시간에 발견한 조용한 골목', '회사 뒤편에 작은 공원이 있었어요. 벤치에서 잠깐 쉬니 오후를 시작할 힘이 났습니다.', '2025-07-18 10:00:00', '2025-07-18 10:00:00', @seojun_id),
    ('매일 들고 다닐 물병을 골랐어요', '가방에 넣기 편한 작은 물병을 샀어요. 뚜껑이 잘 닫히는지 확인하고 내일부터 써 보려고 합니다.', '2025-07-19 10:00:00', '2025-07-19 10:00:00', @seojun_id),
    ('마당에서 별을 보던 저녁', '가족과 불을 끄고 잠깐 하늘을 올려다봤어요. 밝은 별 몇 개를 찾아 이야기하며 시간을 보냈습니다.', '2025-07-20 10:00:00', '2025-07-20 10:00:00', @seojun_id),
    ('우유 팩으로 작은 수납함을 만들었어요', '깨끗이 씻은 팩에 종이를 붙였어요. 책상 위에 흩어진 펜을 모아 두니 제법 쓸 만합니다.', '2025-07-21 10:00:00', '2025-07-21 10:00:00', @seojun_id),
    ('주말 아침 팬케이크를 구웠어요', '반죽을 너무 크게 부어 뒤집기가 어려웠어요. 두 번째부터 작게 구우니 동그란 모양이 잘 나왔습니다.', '2025-07-22 10:00:00', '2025-07-22 10:00:00', @seojun_id),
    ('산책하다 들른 꽃집', '작은 노란 꽃 한 송이를 사 왔어요. 식탁에 올려 두니 평소 먹던 저녁도 조금 특별하게 느껴집니다.', '2025-07-23 10:00:00', '2025-07-23 10:00:00', @seojun_id),
    ('버리지 못하던 종이 상자를 정리했어요', '언젠가 쓰겠지 하며 모아 둔 상자가 많았어요. 필요한 것만 남기니 베란다가 넓어졌습니다.', '2025-07-24 10:00:00', '2025-07-24 10:00:00', @seojun_id),
    ('동네 빵집의 새 메뉴를 먹어 봤어요', '평소 먹던 빵 대신 호두가 든 빵을 골랐어요. 너무 달지 않아서 아침 식사로 잘 어울렸습니다.', '2025-07-25 10:00:00', '2025-07-25 10:00:00', @seojun_id);
INSERT INTO article (title, description, created, updated, member_id) VALUES
    ('수목원에서 오래 머문 나무 그늘', '걷다가 큰 나무 아래에서 쉬었어요. 바람이 불 때마다 잎이 흔들리는 소리가 좋았습니다.', '2025-07-26 10:00:00', '2025-07-26 10:00:00', @kwangcheol_id),
    ('부모님 사진을 앨범에 정리했어요', '휴대전화 속 사진을 골라 인화했어요. 같이 앨범을 보며 그날 이야기를 나누니 시간이 금방 갔습니다.', '2025-07-27 10:00:00', '2025-07-27 10:00:00', @kwangcheol_id),
    ('처음 만든 뜨개 컵받침', '코를 몇 번 놓쳐 모양이 조금 비뚤어요. 그래도 직접 만든 컵받침 위에 차를 올리니 기분이 좋네요.', '2025-07-28 10:00:00', '2025-07-28 10:00:00', @kwangcheol_id),
    ('모처럼 창문을 활짝 열었어요', '바람이 선선해 방 안을 환기했어요. 이불도 정리하고 나니 집에서 보내는 오후가 편안했습니다.', '2025-07-01 10:00:00', '2025-07-01 10:00:00', @kwangcheol_id),
    ('퇴근 후 라디오를 켜 두었어요', '설거지를 하며 듣다가 좋아하는 노래가 나왔어요. 손을 멈추고 잠깐 따라 불렀습니다.', '2025-07-02 10:00:00', '2025-07-02 10:00:00', @kwangcheol_id),
    ('산에서 먹은 김밥이 유난히 맛있었어요', '높지 않은 산을 천천히 올랐어요. 전망대에서 김밥을 나눠 먹고 따뜻한 차를 마셨습니다.', '2025-07-03 10:00:00', '2025-07-03 10:00:00', @kwangcheol_id),
    ('첫 도시락 반찬은 달걀말이', '채소를 잘게 썰어 넣고 여러 번 말았어요. 두툼하게 완성돼서 점심시간이 기다려졌습니다.', '2025-07-04 10:00:00', '2025-07-04 10:00:00', @kwangcheol_id),
    ('비 오는 주말에 보드게임을 했어요', '밖에 나가는 대신 친구들과 모였어요. 설명을 들을 때는 어려웠는데 한 판 해 보니 재미있었습니다.', '2025-07-05 10:00:00', '2025-07-05 10:00:00', @kwangcheol_id),
    ('동네 축제에서 들은 작은 공연', '광장에 의자가 놓여 있어 잠깐 앉았어요. 처음 듣는 밴드였지만 마지막 곡까지 듣고 왔습니다.', '2025-07-06 10:00:00', '2025-07-06 10:00:00', @kwangcheol_id),
    ('낡은 의자에 새 방석을 놓았어요', '오래 쓰던 의자가 조금 딱딱해서 방석을 바꿨어요. 책상 앞에 앉는 시간이 한결 편해졌습니다.', '2025-07-07 10:00:00', '2025-07-07 10:00:00', @kwangcheol_id),
    ('오이무침에 양념을 너무 많이 넣었어요', '조금씩 넣어야 했는데 욕심을 냈어요. 오이를 더 썰어 넣으니 간이 맞아 다행이었습니다.', '2025-07-08 10:00:00', '2025-07-08 10:00:00', @kwangcheol_id),
    ('여행 가방을 가볍게 싸는 중이에요', '입을 옷을 미리 조합해 보고 필요한 것만 골랐어요. 이번에는 작은 가방 하나로 떠나 보려고 합니다.', '2025-07-09 10:00:00', '2025-07-09 10:00:00', @kwangcheol_id),
    ('오후 햇살이 예쁜 카페를 찾았어요', '골목 안쪽에 조용한 카페가 있었어요. 창가 자리에서 차를 마시며 밀린 일기를 썼습니다.', '2025-07-10 10:00:00', '2025-07-10 10:00:00', @kwangcheol_id),
    ('작년 일기를 다시 읽었어요', '잊고 있던 소소한 일이 적혀 있었어요. 오늘도 나중에 웃으며 읽을 수 있도록 몇 줄 남겨 봅니다.', '2025-07-11 10:00:00', '2025-07-11 10:00:00', @kwangcheol_id),
    ('종이 지도를 펼쳐 본 여행 준비', '지도에 가고 싶은 곳을 표시했어요. 가까운 장소끼리 묶으니 이동 경로가 한눈에 보입니다.', '2025-07-12 10:00:00', '2025-07-12 10:00:00', @kwangcheol_id),
    ('비빔국수에 사과를 조금 넣었어요', '얇게 썬 사과를 고명으로 올렸어요. 매콤한 양념 사이로 아삭한 맛이 나서 잘 어울렸습니다.', '2025-07-13 10:00:00', '2025-07-13 10:00:00', @kwangcheol_id),
    ('아침 공원에서 만난 강아지', '보호자와 산책하던 강아지가 잔디 냄새를 맡고 있었어요. 저도 발걸음을 늦추고 천천히 걸었습니다.', '2025-07-14 10:00:00', '2025-07-14 10:00:00', @kwangcheol_id),
    ('집 앞 화단에 새 꽃이 피었어요', '며칠 전까지 봉오리였는데 활짝 피었어요. 오가는 길에 한 번씩 보게 되는 작은 즐거움입니다.', '2025-07-15 10:00:00', '2025-07-15 10:00:00', @kwangcheol_id),
    ('중고 서점에서 절판된 책을 찾았어요', '찾던 책이 서가 구석에 있었어요. 표지에 사용감이 있지만 읽는 데는 전혀 문제가 없었습니다.', '2025-07-16 10:00:00', '2025-07-16 10:00:00', @kwangcheol_id),
    ('콩나물밥에 간장 양념을 곁들였어요', '밥이 뜸 드는 동안 쪽파를 잘게 썰었어요. 따뜻할 때 비벼 먹으니 다른 반찬이 필요 없네요.', '2025-07-17 10:00:00', '2025-07-17 10:00:00', @kwangcheol_id),
    ('디지털 사진첩을 월별로 정리했어요', '같은 사진을 여러 장 찍어 둔 것이 많았어요. 몇 장만 골라 두니 다시 찾아보기가 쉬워졌습니다.', '2025-07-18 10:00:00', '2025-07-18 10:00:00', @kwangcheol_id),
    ('새로 산 공책에 첫 줄을 적었어요', '무엇을 쓸지 고민하다 오늘 있었던 일을 적었어요. 완벽하게 쓰려는 마음을 조금 내려놓으려고 합니다.', '2025-07-19 10:00:00', '2025-07-19 10:00:00', @kwangcheol_id),
    ('수제 잼을 선물받았어요', '친구가 만든 딸기잼을 식빵에 발라 먹었어요. 과육이 씹혀서 아침부터 기분이 좋아졌습니다.', '2025-07-20 10:00:00', '2025-07-20 10:00:00', @kwangcheol_id),
    ('지하철 대신 한 정거장 걸었어요', '급한 일이 없어 천천히 집으로 돌아왔어요. 평소 지나치던 가게들을 구경하는 재미가 있었습니다.', '2025-07-21 10:00:00', '2025-07-21 10:00:00', @kwangcheol_id),
    ('오래된 머그잔을 다시 꺼냈어요', '찬장 안쪽에 넣어 둔 여행 기념품을 찾았어요. 커피를 담으니 그때 걸었던 거리가 생각났습니다.', '2025-07-22 10:00:00', '2025-07-22 10:00:00', @kwangcheol_id);
INSERT INTO article (title, description, created, updated, member_id) VALUES
    ('비 온 뒤 흙냄새가 좋았어요', '잠깐 비가 그친 틈에 공원을 걸었어요. 나뭇잎에 맺힌 물방울이 햇빛을 받아 반짝였습니다.', '2025-07-23 10:00:00', '2025-07-23 10:00:00', @miyeong_id),
    ('친구와 함께 퍼즐을 맞췄어요', '가장자리부터 맞추고 비슷한 색을 모았어요. 마지막 조각이 들어갈 때 둘 다 박수를 쳤습니다.', '2025-07-24 10:00:00', '2025-07-24 10:00:00', @miyeong_id),
    ('가지볶음이 생각보다 간단하네요', '가지를 길게 썰어 양파와 함께 볶았어요. 간장으로 간을 하니 밥과 잘 어울렸습니다.', '2025-07-25 10:00:00', '2025-07-25 10:00:00', @miyeong_id),
    ('주말에 침구를 바꿨어요', '가벼운 이불을 꺼내고 베개 커버도 갈았어요. 정리된 침대에 누우니 하루를 잘 마친 느낌입니다.', '2025-07-26 10:00:00', '2025-07-26 10:00:00', @miyeong_id),
    ('아날로그 시계의 건전지를 갈았어요', '며칠 동안 멈춰 있던 시계가 다시 움직여요. 조용한 방에서 초침 소리가 반갑게 들립니다.', '2025-07-27 10:00:00', '2025-07-27 10:00:00', @miyeong_id),
    ('작은 전시의 방명록을 남겼어요', '마음에 남은 작품 앞에서 오래 서 있었어요. 나오는 길에 작가에게 전하고 싶은 말을 적었습니다.', '2025-07-28 10:00:00', '2025-07-28 10:00:00', @miyeong_id),
    ('텀블러에 담아 간 따뜻한 차', '기차를 기다리는 동안 차를 한 모금 마셨어요. 출발 전의 분주한 마음이 조금 가라앉았습니다.', '2025-07-01 10:00:00', '2025-07-01 10:00:00', @miyeong_id),
    ('동생과 함께 저녁을 준비했어요', '한 사람은 채소를 썰고 다른 사람은 국을 끓였어요. 같이 하니 생각보다 일찍 식탁을 차렸습니다.', '2025-07-02 10:00:00', '2025-07-02 10:00:00', @miyeong_id),
    ('동네 도서관의 새 서가를 둘러봤어요', '요리책과 그림책 코너가 넓어졌어요. 다음 주에는 시간을 내서 천천히 살펴보고 싶습니다.', '2025-07-03 10:00:00', '2025-07-03 10:00:00', @miyeong_id),
    ('오늘은 휴대전화 없이 산책했어요', '사진을 찍는 대신 주변 소리에 귀를 기울였어요. 걸어 온 길의 풍경이 오래 기억에 남습니다.', '2025-07-04 10:00:00', '2025-07-04 10:00:00', @miyeong_id),
    ('남은 식빵으로 마늘빵을 만들었어요', '버터와 다진 마늘을 섞어 얇게 발랐어요. 노릇하게 구워 수프와 함께 먹었습니다.', '2025-07-05 10:00:00', '2025-07-05 10:00:00', @miyeong_id),
    ('바닷가에서 주운 예쁜 돌', '둥글고 매끈한 돌을 한참 바라봤어요. 사진으로만 남기고 다시 모래 위에 놓아두었습니다.', '2025-07-06 10:00:00', '2025-07-06 10:00:00', @miyeong_id),
    ('창틀을 닦고 커튼을 빨았어요', '미뤄 둔 청소를 끝내니 방이 더 밝아 보여요. 깨끗해진 창으로 들어오는 햇빛이 좋았습니다.', '2025-07-07 10:00:00', '2025-07-07 10:00:00', @miyeong_id),
    ('오랜 친구와 오래된 사진을 봤어요', '서로 잊고 있던 이야기를 꺼내며 웃었어요. 다음에는 다른 친구들도 함께 만나기로 했습니다.', '2025-07-08 10:00:00', '2025-07-08 10:00:00', @miyeong_id),
    ('버섯을 넣은 달걀찜', '달걀물에 잘게 썬 버섯을 넣었어요. 부드럽게 익어서 저녁 반찬으로 맛있게 먹었습니다.', '2025-07-09 10:00:00', '2025-07-09 10:00:00', @miyeong_id),
    ('새 운동복을 입고 공원에 갔어요', '빨리 달리기보다는 일정한 속도로 걸었어요. 벤치에서 쉬며 물을 마시고 천천히 돌아왔습니다.', '2025-07-10 10:00:00', '2025-07-10 10:00:00', @miyeong_id),
    ('현관 앞에 작은 우산꽂이를 뒀어요', '젖은 우산을 놓을 자리가 생겼어요. 외출할 때 우산을 찾느라 헤매는 일도 줄 것 같습니다.', '2025-07-11 10:00:00', '2025-07-11 10:00:00', @miyeong_id),
    ('엄마에게 배운 멸치볶음', '옆에서 불 조절하는 방법을 배웠어요. 식힌 뒤 맛을 보니 너무 딱딱하지 않게 잘 만들어졌습니다.', '2025-07-12 10:00:00', '2025-07-12 10:00:00', @miyeong_id),
    ('공원 벤치에서 듣던 음악', '이어폰으로 잔잔한 곡을 들었어요. 눈앞에서 바람에 흔들리는 나무와 잘 어울렸습니다.', '2025-07-13 10:00:00', '2025-07-13 10:00:00', @miyeong_id),
    ('잠들기 전에 그림책을 읽었어요', '글이 짧아도 그림을 자세히 보니 이야기가 많았어요. 어릴 때와는 다른 장면이 마음에 남네요.', '2025-07-14 10:00:00', '2025-07-14 10:00:00', @miyeong_id),
    ('오래된 가방의 지퍼를 고쳤어요', '동네 수선집에 맡겼더니 다시 부드럽게 열려요. 익숙한 가방을 더 쓸 수 있어 좋았습니다.', '2025-07-15 10:00:00', '2025-07-15 10:00:00', @miyeong_id),
    ('토마토 달걀볶음을 처음 해 봤어요', '토마토를 충분히 볶고 달걀을 섞었어요. 따뜻한 밥 위에 올려 간단하게 저녁을 먹었습니다.', '2025-07-16 10:00:00', '2025-07-16 10:00:00', @miyeong_id),
    ('달력에 가족 생일을 표시했어요', '휴대전화 알림만 믿다가 놓칠까 봐 적어 뒀어요. 올해는 미리 편지도 준비하려고 합니다.', '2025-07-17 10:00:00', '2025-07-17 10:00:00', @miyeong_id),
    ('철길 옆 산책로를 걸었어요', '기차가 지나갈 때마다 잠깐 멈춰 구경했어요. 길 끝에 있는 작은 분식집에서 떡볶이도 먹었습니다.', '2025-07-18 10:00:00', '2025-07-18 10:00:00', @miyeong_id),
    ('냉동실 재료로 끓인 떡국', '남은 떡과 대파를 꺼내 한 그릇 끓였어요. 달걀을 풀어 넣으니 든든한 점심이 되었습니다.', '2025-07-19 10:00:00', '2025-07-19 10:00:00', @miyeong_id);
INSERT INTO article (title, description, created, updated, member_id) VALUES
    ('친구가 추천한 영화를 봤어요', '잔잔한 이야기였는데 마지막 장면이 오래 남았어요. 영화를 본 뒤 친구에게 감상을 길게 보냈습니다.', '2025-07-20 10:00:00', '2025-07-20 10:00:00', @doyun_id),
    ('나무 도마에 기름을 발랐어요', '깨끗이 씻어 말린 뒤 도마용 오일을 얇게 발랐어요. 결이 선명해져서 새것처럼 보입니다.', '2025-07-21 10:00:00', '2025-07-21 10:00:00', @doyun_id),
    ('공책에 이번 달 지출을 적었어요', '작은 간식값이 모이니 꽤 큰 금액이 되었어요. 다음 달에는 집에서 간식을 준비해 보려고 합니다.', '2025-07-22 10:00:00', '2025-07-22 10:00:00', @doyun_id),
    ('산책 중 발견한 작은 연못', '수면에 하늘과 나무가 비쳐 있었어요. 벤치에 앉아 잠시 물결을 바라보다 돌아왔습니다.', '2025-07-23 10:00:00', '2025-07-23 10:00:00', @doyun_id),
    ('감자조림 양념이 잘 배었어요', '감자를 너무 크지 않게 썰어 졸였어요. 식탁에 올리기도 전에 하나씩 집어 먹게 되네요.', '2025-07-24 10:00:00', '2025-07-24 10:00:00', @doyun_id),
    ('바람 부는 날 빨래를 널었어요', '수건이 금방 말라서 오후에 걷을 수 있었어요. 햇볕 냄새가 나는 수건을 접으니 뿌듯했습니다.', '2025-07-25 10:00:00', '2025-07-25 10:00:00', @doyun_id),
    ('처음 들른 동네 재래시장', '반찬가게와 떡집을 구경하며 한 바퀴 돌았어요. 다음에는 장바구니를 조금 더 큰 것으로 가져가야겠어요.', '2025-07-26 10:00:00', '2025-07-26 10:00:00', @doyun_id),
    ('손목시계 줄을 바꿨어요', '가죽 줄 대신 가벼운 천 소재를 골랐어요. 오래 쓰던 시계가 다른 분위기로 보여서 마음에 듭니다.', '2025-07-27 10:00:00', '2025-07-27 10:00:00', @doyun_id),
    ('저녁으로 채소전을 부쳤어요', '양배추와 당근을 얇게 썰어 넣었어요. 냉장고 속 자투리 채소를 쓰기에 좋은 메뉴였습니다.', '2025-07-28 10:00:00', '2025-07-28 10:00:00', @doyun_id),
    ('동네 공원에 새 벤치가 생겼어요', '그늘 아래 놓여 있어 잠깐 앉아 봤어요. 산책하다 쉬어 갈 자리가 늘어서 반갑습니다.', '2025-07-01 10:00:00', '2025-07-01 10:00:00', @doyun_id),
    ('달걀 샌드위치를 싸서 나갔어요', '삶은 달걀을 으깨 식빵 사이에 넣었어요. 공원에서 먹으니 평소보다 맛있게 느껴졌습니다.', '2025-07-02 10:00:00', '2025-07-02 10:00:00', @doyun_id),
    ('작은 화분 받침을 직접 골랐어요', '물받이 크기를 재고 가서 알맞은 것을 샀어요. 창가 선반을 닦기도 편해졌습니다.', '2025-07-03 10:00:00', '2025-07-03 10:00:00', @doyun_id),
    ('봄옷을 꺼내며 옷장을 정리했어요', '지난겨울에 입지 않은 옷은 따로 모았어요. 자주 입는 옷이 잘 보이니 아침 준비가 빨라질 것 같습니다.', '2025-07-04 10:00:00', '2025-07-04 10:00:00', @doyun_id),
    ('공연장 가는 길에 길을 잘못 들었어요', '조금 돌아갔지만 예쁜 골목을 발견했어요. 다행히 공연 시작 전에는 자리에 앉을 수 있었습니다.', '2025-07-05 10:00:00', '2025-07-05 10:00:00', @doyun_id),
    ('저녁 하늘에 달이 밝았어요', '집에 가는 길에 건물 사이로 달이 보였어요. 잠시 멈춰 바라보는 동안 마음이 차분해졌습니다.', '2025-07-06 10:00:00', '2025-07-06 10:00:00', @doyun_id),
    ('처음 만든 두부조림이 성공했어요', '두부를 먼저 노릇하게 굽고 양념을 넣었어요. 부서지지 않아 그릇에 담기도 수월했습니다.', '2025-07-07 10:00:00', '2025-07-07 10:00:00', @doyun_id),
    ('카페에서 엽서를 한 장 샀어요', '창가 풍경을 그린 엽서가 마음에 들었어요. 책상 앞에 붙여 두고 가끔 여행 생각을 합니다.', '2025-07-08 10:00:00', '2025-07-08 10:00:00', @doyun_id),
    ('가족과 동네 둘레길을 걸었어요', '서로 속도를 맞추며 천천히 걸었어요. 중간에 간식을 나눠 먹고 사진도 찍었습니다.', '2025-07-09 10:00:00', '2025-07-09 10:00:00', @doyun_id),
    ('헌 책 속에서 오래된 책갈피를 찾았어요', '언제 끼워 뒀는지 기억나지 않는 종이가 나왔어요. 적혀 있던 메모를 읽고 한참 웃었습니다.', '2025-07-10 10:00:00', '2025-07-10 10:00:00', @doyun_id),
    ('차가운 국수로 점심을 먹었어요', '삶은 면을 찬물에 헹구고 오이를 얹었어요. 더운 날이라 시원한 한 그릇이 반가웠습니다.', '2025-07-11 10:00:00', '2025-07-11 10:00:00', @doyun_id),
    ('부엌 서랍에 칸막이를 넣었어요', '수저와 조리 도구를 나눠 담았어요. 서랍을 열 때마다 물건이 섞이지 않아 편합니다.', '2025-07-12 10:00:00', '2025-07-12 10:00:00', @doyun_id),
    ('비가 그친 뒤 무지개를 봤어요', '구름 사이로 햇빛이 나더니 희미한 무지개가 생겼어요. 같이 걷던 친구와 동시에 하늘을 가리켰습니다.', '2025-07-13 10:00:00', '2025-07-13 10:00:00', @doyun_id),
    ('오늘은 직접 내린 차를 마셨어요', '찻잎이 우러나는 동안 잠깐 기다렸어요. 서두르지 않고 마시는 시간이 생각보다 좋았습니다.', '2025-07-14 10:00:00', '2025-07-14 10:00:00', @doyun_id),
    ('혼자 먹는 저녁에도 식탁을 차렸어요', '그릇을 꺼내 반찬을 조금씩 담았어요. 간단한 식사지만 자리에 앉아 천천히 먹었습니다.', '2025-07-15 10:00:00', '2025-07-15 10:00:00', @doyun_id),
    ('이번 주에 고마웠던 일을 적었어요', '작은 도움을 받았던 순간들을 떠올렸어요. 다음 주에는 저도 먼저 안부를 건네 보려고 합니다.', '2025-07-16 10:00:00', '2025-07-16 10:00:00', @doyun_id);
